## 9. Testing Your API

### 9.1 Unit Tests (Moq)

```csharp
[Fact]
public async Task GetById_ReturnsNotFound_WhenBookDoesNotExist()
{
    // Arrange
    var mockRepo = new Mock<IBookRepository>();
    mockRepo.Setup(r => r.GetByIdAsync(It.IsAny<Guid>(), It.IsAny<CancellationToken>()))
            .ReturnsAsync((Book?)null);
    var controller = new BooksController(mockRepo.Object, new Mapper(new MapperConfiguration(cfg => cfg.AddProfile<BookMappingProfile>())));

    // Act
    var result = await controller.Get(Guid.NewGuid());

    // Assert
    Assert.IsType<NotFoundResult>(result.Result);
}
```

### 9.2 Integration Tests (WebApplicationFactory)

```csharp
public class BooksApiTests : IClassFixture<WebApplicationFactory<Program>>
{
    private readonly HttpClient _client;
    public BooksApiTests(WebApplicationFactory<Program> factory)
    {
        _client = factory.CreateClient();
    }

    [Fact]
    public async Task GetAll_ReturnsOk()
    {
        var response = await _client.GetAsync("/api/books");
        response.EnsureSuccessStatusCode();

        var content = await response.Content.ReadFromJsonAsync<List<BookDto>>();
        Assert.NotNull(content);
    }
}
```

