## 13. Quick Reference – Minimal API Skeleton (Net 7+)

```csharp
var builder = WebApplication.CreateBuilder(args);

// Services
builder.Services.AddDbContext<AppDbContext>(opt =>
    opt.UseSqlServer(builder.Configuration.GetConnectionString("DefaultConnection")));
builder.Services.AddScoped<IEntityRepository<Book>, BookRepository>();
builder.Services.AddAutoMapper(typeof(Program));
builder.Services.AddEndpointsApiExplorer();
builder.Services.AddSwaggerGen();
builder.Services.AddCors(opt => opt.AddDefaultPolicy(p => p.AllowAnyOrigin().AllowAnyHeader().AllowAnyMethod()));

var app = builder.Build();

// Middleware
app.UseSwagger();
app.UseSwaggerUI();
app.UseHttpsRedirection();
app.UseCors();
app.UseAuthorization();

// Endpoints
app.MapGet("/api/books", async (IBookRepository repo, IMapper mapper) =>
    Results.Ok(mapper.Map<IEnumerable<BookDto>>(await repo.GetAllAsync())))
   .WithName("GetAllBooks")
   .Produces<IEnumerable<BookDto>>();

app.MapGet("/api/books/{id}", async (Guid id, IBookRepository repo, IMapper mapper) =>
{
    var book = await repo.GetByIdAsync(id);
    return book is null ? Results.NotFound() : Results.Ok(mapper.Map<BookDto>(book));
})
   .WithName("GetBookById")
   .Produces<BookDto>();

app.MapPost("/api/books", async (BookDto dto, IBookRepository repo, IMapper mapper) =>
{
    var book = mapper.Map<Book>(dto);
    book.Id = Guid.NewGuid();
    await repo.AddAsync(book);
    return Results.Created($"/api/books/{book.Id}", mapper.Map<BookDto>(book));
})
   .WithName("CreateBook")
   .Produces<BookDto>();

app.MapPut("/api/books/{id}", async (Guid id, BookDto dto, IBookRepository repo, IMapper mapper) =>
{
    if (id != dto.Id) return Results.BadRequest();
    var updated = await repo.UpdateAsync(mapper.Map<Book>(dto));
    return updated is null ? Results.NotFound() : Results.Ok(mapper.Map<BookDto>(updated));
})
   .WithName("UpdateBook")
   .Produces<BookDto>();

app.MapDelete("/api/books/{id}", async (Guid id, IBookRepository repo) =>
{
    var deleted = await repo.DeleteAsync(id);
    return deleted ? Results.NoContent() : Results.NotFound();
})
   .WithName("DeleteBook");

app.Run();
```

